{
  "book_code": "4BAR",
  "verses": [
    {
      "chapter": 7,
      "text_ar": "ولا تحد يمنة أو يسرة، بل امضِ مستقيماً كسههم مسرع في قوة الله، ويكون مجد الرب معك في طوال الطريق.",
      "verse": 11
    },
    {
      "chapter": 7,
      "text_ar": "حينئذ طار النسر وذهب إلى بابل والرسالة مربوطة بعنقه، ولما وصل استراح على عمود خارج المدينة في مكان مقفر.",
      "verse": 12
    },
    {
      "chapter": 7,
      "text_ar": "وبقي صامتاً حتى أتى إرميا، لأنه هو وبعض الشعب كانوا خارجين لدفن جثة خارج المدينة.",
      "verse": 13
    },
    {
      "chapter": 7,
      "text_ar": "لأن إرميا كان قد التمس من الملك نبوخذ ناصر قائلاً: أعطني مكاناً أدفن فيه أموات شعبي. فأعطاه إياه الملك.",
      "verse": 14
    },
    {
      "chapter": 7,
      "text_ar": "وبينما كانوا خارجين بالجسد وهم يبكون، وصلوا إلى حيث كان النسر.",
      "verse": 15
    }
  ]
}
